    text: 'アナトリア北西部でオスマン1世が建てたトルコ人の国家。バルカン半島に進出し、1453年にメフメト2世がコンスタンティノープルを攻略してビザンツ帝国をほろぼした。セリム1世はマムルーク朝をほろぼして聖地メッカ・メディナの保護者となり、スレイマン1世の時代には第1次ウィーン包囲やプレヴェザの海戦で最盛期をむかえた。異教徒の共同体（ミッレト）に自治を認め、イェニチェリやティマール制で支えられた。17世紀末の第2次ウィーン包囲の失敗以後は領土を失い、19世紀にはタンジマートなどの改革をおこなったが「瀕死の病人」とよばれ、第一次世界大戦後に滅亡した。',
